def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    urgent_opp_count = 0
    rich_opp_count = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_opp_count += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    desperation = 0
    if hp <= 2:
        desperation += 3
    elif hp <= 4:
        desperation += 2
    elif hp <= 6:
        desperation += 1

    if no_water_days >= 2:
        desperation += 3
    elif no_water_days >= 1:
        desperation += 1

    if tight_supply:
        desperation += 1

    if day >= 8:
        desperation += 1

    if desperation >= 5:
        bid = 96.0
        if highest_prev > 0:
            bid = max(bid, min(112.0, highest_prev + 2.0))
    elif desperation >= 3:
        if highest_prev >= 110:
            bid = 62.0
        elif highest_prev >= 85:
            bid = highest_prev + 1.5
        elif highest_prev > 0:
            bid = max(48.0, avg_prev + 3.0)
        else:
            bid = 52.0
    else:
        if loose_supply and hp >= 7 and no_water_days == 0:
            if highest_prev >= 110:
                bid = 16.0
            elif highest_prev >= 90:
                bid = 22.0
            else:
                bid = 28.0
        else:
            if highest_prev >= 120:
                bid = 20.0
            elif highest_prev >= 100:
                bid = 26.0
            elif highest_prev >= 80:
                bid = 34.0
            elif highest_prev > 0:
                bid = max(30.0, min(46.0, highest_prev + 1.0))
            else:
                bid = 32.0

    if rich_opp_count >= 2 and tight_supply and desperation >= 3:
        bid += 8.0
    elif urgent_opp_count >= 2 and desperation <= 2:
        bid -= 4.0

    reserve_floor = 0.0
    if hp >= 6 and no_water_days == 0:
        reserve_floor = 0.55 * DAILY_SALARY
    elif hp >= 4:
        reserve_floor = 0.35 * DAILY_SALARY
    else:
        reserve_floor = 0.15 * DAILY_SALARY

    max_affordable = budget
    if budget > reserve_floor:
        max_affordable = budget - reserve_floor + min(reserve_floor, 18.0)

    if desperation >= 5:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append(o)

    # If no opponents, buy enough to cover requirement
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace only
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            prev_bids.append(float(b))

    # Estimate opponent aggressiveness
    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev = 0.0
        avg_prev = DAILY_SALARY * 0.6

    # Supply pressure: higher supply reduces need to overbid
    # Map supply range [15,25] to a pressure factor in [1.15,0.85]
    if MAX_SUPPLY != MIN_SUPPLY:
        t = (float(supply) - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    if t < 0.0:
        t = 0.0
    if t > 1.0:
        t = 1.0
    pressure = 1.15 - 0.30 * t

    # HP-based urgency
    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    # Base bid target: slightly above average, but below highest to preserve budget
    # Use highest_prev to react to aggressive meta.
    # Target band depends on our HP.
    if hp <= 2.0:
        hp_factor = 0.95
    elif hp <= 4.0:
        hp_factor = 0.80
    elif hp <= 7.0:
        hp_factor = 0.68
    else:
        hp_factor = 0.60

    # Compute a candidate bid
    # If opponents were very aggressive yesterday, we try to beat them but not fully match max.
    aggressive_threshold = DAILY_SALARY * 0.85
    if highest_prev >= aggressive_threshold:
        # Beat the pack: aim at 0.92*highest or 1.05*avg, whichever is lower
        target = min(0.92 * highest_prev, 1.05 * avg_prev)
    else:
        # Normal: aim around 1.00*avg_prev, with pressure adjustment
        target = 1.00 * avg_prev

    target = target * float(pressure) * float(hp_factor)

    # Ensure we don't exceed budget
    bid = min(budget, target)

    # Safety floor: if we are bidding too low relative to typical prices, raise slightly
    # to avoid being consistently outbid.
    min_reasonable = max(DAILY_SALARY * 0.35, 0.55 * avg_prev)
    if bid < min_reasonable:
        bid = min(budget, min_reasonable * float(pressure) * 0.95)

    # If budget is very low, still bid something proportional to avoid total starvation
    if bid <= 0.0:
        bid = min(budget, DAILY_SALARY * 0.1)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    MIN_SUPPLY = 15.0
    MAX_SUPPLY = 25.0

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid_amount = DAILY_SALARY * 0.65

    if my_hp <= 2 or my_no_water_days > 0:
        bid_amount = DAILY_SALARY * 0.98
    elif my_hp <= 4:
        bid_amount = DAILY_SALARY * 0.90

    days_remaining = EPISODE_DAYS - current_day
    if days_remaining <= 2:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.95)
    elif days_remaining <= 5:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.80)

    scarcity_factor = (MAX_SUPPLY - current_supply) / (MAX_SUPPLY - MIN_SUPPLY)
    bid_amount += scarcity_factor * (DAILY_SALARY * 0.15)

    if highest_prev_bid > 0:
        competitive_bid = highest_prev_bid + 2.0

        if my_hp <= 4 or my_no_water_days > 0:
            bid_amount = max(bid_amount, competitive_bid)
            bid_amount = min(bid_amount, DAILY_SALARY * 1.1)
        else:
            if competitive_bid < DAILY_SALARY * 0.9:
                bid_amount = max(bid_amount, competitive_bid)
            else:
                bid_amount = max(bid_amount, DAILY_SALARY * 0.75)
                bid_amount = min(bid_amount, DAILY_SALARY * 0.95)

    final_bid = max(1.0, min(my_budget, bid_amount))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    avg_bid_needed = supply / (len(alive_opponents) + 1)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if 'previous_trace' in o and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], DAILY_SALARY * 0.95))

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev > DAILY_SALARY * 0.7:
            return float(min(my_status['budget'], DAILY_SALARY * 0.3))
        return float(min(my_status['budget'], max(avg_bid_needed * 1.1, max_prev + 2.0)))

    return float(min(my_status['budget'], DAILY_SALARY * 0.5))
